package net.officefloor.hq.app.project;

import java.util.List;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.client.ClientRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ProjectService {

    private final ProjectRepository projects;
    private final ClientRepository clients;

    public ProjectService(ProjectRepository projects, ClientRepository clients) {
        this.projects = projects;
        this.clients = clients;
    }

    @Transactional(readOnly = true)
    public List<ProjectResponse> list() {
        return projects.findAllWithClient().stream().map(ProjectResponse::from).toList();
    }

    @Transactional(readOnly = true)
    public List<ProjectResponse> listForClient(Long clientId) {
        if (!clients.existsById(clientId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
        return projects.findByClientIdWithClient(clientId).stream().map(ProjectResponse::from).toList();
    }

    @Transactional(readOnly = true)
    public ProjectResponse get(Long id) {
        return projects.findByIdWithClient(id).map(ProjectResponse::from)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
    }

    @Transactional
    public ProjectResponse create(ProjectRequest request) {
        Client client = clients.findById(request.clientId())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown client"));
        Project saved = projects.save(new Project(request.name().trim(), client));
        return ProjectResponse.from(saved);
    }
}
package net.officefloor.hq.app.project;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface ProjectRepository extends JpaRepository<Project, Long> {

    /** All projects with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client ORDER BY p.id")
    List<Project> findAllWithClient();

    /** A client's projects with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client c WHERE c.id = :clientId ORDER BY p.id")
    List<Project> findByClientIdWithClient(Long clientId);

    /** One project with its client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client WHERE p.id = :id")
    Optional<Project> findByIdWithClient(Long id);

    /** How many projects a client has. */
    long countByClientId(Long clientId);
}
package net.officefloor.hq.app.project;

import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import net.officefloor.hq.app.client.Client;

/** A project done for a client. */
@Entity
@Table(name = "project")
public class Project {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "client_id", nullable = false)
    private Client client;

    protected Project() {
    }

    public Project(String name, Client client) {
        this.name = name;
        this.client = client;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public Client getClient() {
        return client;
    }
}
import { Component, inject, signal } from '@angular/core';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { Client, ClientService } from '../clients/client.service';
import { Project, ProjectService } from './project.service';

// Projects page: add a project for a client and list all projects with their client's name; each
// project opens its detail page.
@Component({
  selector: 'app-projects',
  imports: [ReactiveFormsModule, RouterLink],
  template: `
    <h1>Projects</h1>

    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="project-form" novalidate>
      <div>
        <label for="project-name">Name</label>
        <input
          id="project-name"
          type="text"
          formControlName="name"
          data-testid="project-form-name"
          [attr.aria-invalid]="showError('name')"
          [attr.aria-describedby]="showError('name') ? 'project-name-error' : null"
        />
        @if (showError('name')) {
          <p id="project-name-error" role="alert" data-testid="project-form-name-error">
            Name is required.
          </p>
        }
      </div>
      <div>
        <label for="project-client">Client</label>
        <select
          id="project-client"
          formControlName="clientId"
          data-testid="project-form-client"
          [attr.aria-invalid]="showError('clientId')"
          [attr.aria-describedby]="showError('clientId') ? 'project-client-error' : null"
        >
          <option value="">Select a client</option>
          @for (c of clients(); track c.id) {
            <option [value]="c.id">{{ c.name }}</option>
          }
        </select>
        @if (showError('clientId')) {
          <p id="project-client-error" role="alert" data-testid="project-form-client-error">
            Choose a client.
          </p>
        }
      </div>
      <button type="submit" data-testid="project-form-submit" [disabled]="saving()">
        Add project
      </button>
      @if (saveError()) {
        <p role="alert" data-testid="project-form-error">{{ saveError() }}</p>
      }
    </form>

    @if (projects().length === 0) {
      <p data-testid="projects-empty">No projects yet.</p>
    } @else {
      <table data-testid="projects-table">
        <caption>All projects</caption>
        <thead>
          <tr>
            <th scope="col">Name</th>
            <th scope="col">Client</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th>
          </tr>
        </thead>
        <tbody>
          @for (p of projects(); track p.id) {
            <tr [attr.data-testid]="'project-row-' + p.id">
              <td data-testid="project-name">{{ p.name }}</td>
              <td data-testid="project-client">{{ p.clientName }}</td>
              <td>
                <a
                  [routerLink]="['/projects', p.id]"
                  [attr.data-testid]="'project-open-' + p.id"
                  [attr.aria-label]="'Open ' + p.name"
                  >Open</a
                >
              </td>
            </tr>
          }
        </tbody>
      </table>
    }
  `,
})
export class Projects {
  private readonly service = inject(ProjectService);
  private readonly clientService = inject(ClientService);

  protected readonly projects = signal<Project[]>([]);
  protected readonly clients = signal<Client[]>([]);
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    name: ['', [Validators.required, Validators.maxLength(255)]],
    clientId: ['', Validators.required],
  });

  constructor() {
    this.service.list().subscribe((list) => this.projects.set(list));
    this.clientService.list().subscribe((list) => this.clients.set(list));
  }

  protected showError(field: 'name' | 'clientId'): boolean {
    const control = this.form.controls[field];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid || !this.form.getRawValue().name.trim()) {
      this.form.markAllAsTouched();
      return;
    }
    const { name, clientId } = this.form.getRawValue();
    this.saving.set(true);
    this.saveError.set(null);
    this.service.create({ name: name.trim(), clientId: Number(clientId) }).subscribe({
      next: (created) => {
        this.projects.update((list) => [...list, created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the project. Please try again.');
        this.saving.set(false);
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Project {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
}

export interface NewProject {
  name: string;
  clientId: number;
}

@Injectable({ providedIn: 'root' })
export class ProjectService {
  private readonly http = inject(HttpClient);

  list(): Observable<Project[]> {
    return this.http.get<Project[]>('/api/projects');
  }

  listForClient(clientId: number): Observable<Project[]> {
    return this.http.get<Project[]>(`/api/clients/${clientId}/projects`);
  }

  get(id: number): Observable<Project> {
    return this.http.get<Project>(`/api/projects/${id}`);
  }

  create(project: NewProject): Observable<Project> {
    return this.http.post<Project>('/api/projects', project);
  }
}
-- An invoice is built from line items: a description, how many, and the price of each. The
-- invoice amount is the sum of each line's quantity times unit price, so a draft with no lines yet
-- is worth zero.
CREATE TABLE invoice_line_item (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id  BIGINT         NOT NULL,
    description VARCHAR(255)   NOT NULL,
    qty         DECIMAL(10, 2) NOT NULL,
    unit_price  DECIMAL(12, 2) NOT NULL,
    CONSTRAINT invoice_line_item_invoice_fk FOREIGN KEY (invoice_id) REFERENCES invoice (id),
    CONSTRAINT invoice_line_item_qty_positive CHECK (qty > 0),
    CONSTRAINT invoice_line_item_unit_price_positive CHECK (unit_price > 0)
);

CREATE INDEX invoice_line_item_invoice_idx ON invoice_line_item (invoice_id);

ALTER TABLE invoice DROP CONSTRAINT invoice_amount_positive;
ALTER TABLE invoice ADD CONSTRAINT invoice_amount_not_negative CHECK (amount >= 0);

-- Existing invoices were raised as one figure: carry that figure over as a single line.
INSERT INTO invoice_line_item (invoice_id, description, qty, unit_price)
SELECT id, 'Invoice amount', 1, amount FROM invoice;
CREATE TABLE client (
    id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name  VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL
);
-- Every client must have a well-formed email (local@domain.tld); backstop for the API validation.
ALTER TABLE client ADD CONSTRAINT client_email_format
    CHECK (email LIKE '_%@_%._%' AND email NOT LIKE '% %');
CREATE TABLE project (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name      VARCHAR(255) NOT NULL,
    client_id BIGINT       NOT NULL,
    CONSTRAINT project_client_fk FOREIGN KEY (client_id) REFERENCES client (id)
);

CREATE INDEX project_client_idx ON project (client_id);
CREATE TABLE invoice (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    CONSTRAINT invoice_project_fk FOREIGN KEY (project_id) REFERENCES project (id),
    CONSTRAINT invoice_amount_positive CHECK (amount > 0)
);

CREATE INDEX invoice_project_idx ON invoice (project_id);
ALTER TABLE invoice ADD COLUMN status VARCHAR(16) DEFAULT 'UNPAID' NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid CHECK (status IN ('UNPAID', 'PAID'));
-- Every invoice carries the date it was issued (sent out) and the date payment is due.
-- Backfill any existing rows: issued today, due 30 days later.
ALTER TABLE invoice ADD COLUMN issued_date DATE DEFAULT CURRENT_DATE NOT NULL;
ALTER TABLE invoice ADD COLUMN due_date DATE;
UPDATE invoice SET due_date = DATEADD('DAY', 30, issued_date) WHERE due_date IS NULL;
ALTER TABLE invoice ALTER COLUMN due_date SET NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_due_after_issued CHECK (due_date >= issued_date);
-- Invoices move through a lifecycle: DRAFT -> SENT -> PAID. New invoices start as drafts.
-- Existing unpaid invoices had already been issued, so they become SENT.
ALTER TABLE invoice DROP CONSTRAINT invoice_status_valid;
UPDATE invoice SET status = 'SENT' WHERE status = 'UNPAID';
ALTER TABLE invoice ALTER COLUMN status SET DEFAULT 'DRAFT';

ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid CHECK (status IN ('DRAFT', 'SENT', 'PAID'));
CREATE TABLE contact (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT       NOT NULL,
    name      VARCHAR(255) NOT NULL,
    email     VARCHAR(255) NOT NULL,
    role      VARCHAR(255) NOT NULL,
    CONSTRAINT contact_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    -- Backstop for the API validation, matching the client email rule.
    CONSTRAINT contact_email_format CHECK (email LIKE '_%@_%._%' AND email NOT LIKE '% %')
);

CREATE INDEX contact_client_idx ON contact (client_id);
CREATE TABLE task (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT       NOT NULL,
    title      VARCHAR(255) NOT NULL,
    done       BOOLEAN      NOT NULL DEFAULT FALSE,
    CONSTRAINT task_project_fk FOREIGN KEY (project_id) REFERENCES project (id)
);

CREATE INDEX task_project_idx ON task (project_id);
